const d = $input.first().json;

// 1. Data Summary
const total = d.totals.total_units;
const deployed = d.totals.deployed;
const rate = d.totals.deployment_rate_pct;
const onHold = d.totals.on_hold;

// 2. Bottlenecks
const topStuck = d.bottlenecks || [];
const stuckLabels = topStuck.map(b => `${b.customer_name.slice(0, 15)} (${b.avg_waiting_days}d)`);
const stuckCounts = topStuck.map(b => b.waiting_units);

// 3. QuickChart Config untuk Grafik Batang Bottleneck
const chartConfig = {
  type: 'horizontalBar',
  data: {
    labels: stuckLabels,
    datasets: [{
      label: 'Unit Menunggu Jadwal',
      data: stuckCounts,
      backgroundColor: 'rgba(239, 68, 68, 0.85)'
    }]
  },
  options: {
    title: { display: true, text: 'Top 5 Customer Bottlenecks (Days Waiting)' },
    scales: { xAxes: [{ ticks: { beginAtZero: true } }] }
  }
};
const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}&w=650&h=320`;

// 4. Susun Narasi Eksekutif (HTML)
let reportText = `📊 <b>WEEKLY OPERATIONS EXECUTIVE REPORT</b>\n`;
reportText += `<i>Periode: ${new Date(d.generated_at).toLocaleDateString('id-ID', { dateStyle: 'long' })}</i>\n\n`;

reportText += `<b>1. EXECUTIVE HIGHLIGHTS</b>\n`;
reportText += `• Deployment Rate: <b>${rate}%</b> (${deployed} dari ${total} unit rampung)\n`;
reportText += `• Pipeline Aktif: <b>${d.totals.in_progress} unit</b> sedang berjalan di lapangan\n`;
reportText += `• Unit On Hold: <b>${onHold} unit</b> (butuh eskalasi PIC/Vendor)\n\n`;

reportText += `<b>2. LEAD TIME & SLA METRICS</b>\n`;
reportText += `• Internal Cycle (PO ➔ QC): <b>${d.kpi_lead_times.internal_lead_days} hari</b>\n`;
reportText += `• Customer Response Time: <b>${d.kpi_lead_times.customer_response_days} hari</b>\n`;
reportText += `• Insiden Reschedule: <b>${d.kpi_lead_times.total_reschedules} kali</b>\n\n`;

reportText += `<b>3. TOP BOTTLENECKS (ACTION REQUIRED)</b>\n`;
topStuck.forEach((b, idx) => {
  reportText += `${idx+1}. <b>${b.customer_name}</b>: ${b.waiting_units} unit macet (${b.avg_waiting_days} hari) | PIC AM: ${b.am_name}\n`;
});
reportText += `\n<i>Rekomendasi: Follow up prioritas customer di atas untuk konfirmasi tanggal cut-off jadwal sebelum hari Senin.</i>`;

return [{
  json: {
    chart_url: chartUrl,
    caption: reportText
  }
}];
